function ScoringFunctions_FishingBoat(aiPlayer)	
	-- scoring function for max pop of fishing boats depending on a limited naval or fully naval map
	function fishingBoatPopulationScoring(aiPlayer)
		-- less fishing boats on a limited naval map
		local limitedNavalPopulationList = {
			AIProductionScoring_ShouldConsiderLimitedNaval(aiPlayer),
			AIProductionScoring_MaxPopCapPercentage(aiPlayer, 0.03, true),
		}

		-- scoring for max pop when on a full naval map
		local fullNavalPopulationList = {
			AIProductionScoring_ShouldConsiderNaval(aiPlayer),
			AIProductionScoring_MaxPopCapPercentage(aiPlayer, 0.1, true),
		}

		-- likely neither limited nor full naval, but we have deepwater fish on the map
		local generalDeepwaterFishPopulationList = {
			AIProductionScoring_ShouldConsiderDeepwaterFishDeposits(aiPlayer),
			AIProductionScoring_MaxPopCapPercentage(aiPlayer, 0.03, true),
		}

		local limitedNavalPopScoring = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, limitedNavalPopulationList)
		local fullNavalPopScoring = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, fullNavalPopulationList)
		local generalDeepwaterFishPopScoring = AIProductionScoring_MultiplyListScoringFunction(aiPlayer, generalDeepwaterFishPopulationList)

		return AIProductionScoring_MaxScoringFunction(aiPlayer, {limitedNavalPopScoring, fullNavalPopScoring, generalDeepwaterFishPopScoring})
	end

	-- Fishing boats are also used as scouts so we need a minimum number of them for that purpose
	function MinimumTwoScouts(aiPlayer)
		local underTwoOrPopulationPercentage = {
			AIProductionScoring_PopulationPercentage(aiPlayer, 1.0, 0.5, false, true),
			AIProductionScoring_UnderCountLimit(aiPlayer, 3, -1, true)
		}

		return AIProductionScoring_MaxScoringFunction(aiPlayer, underTwoOrPopulationPercentage) 
	end

	local result = {
		AIProductionScoring_ShouldConsiderDeepwaterFishDeposits(aiPlayer),
		AIProductionScoring_TimeToAcquire(aiPlayer, 300.0, true, false, true),
		AIProductionScoring_StrategicIntention(aiPlayer, { ["economy"] = 1.0 }),
		fishingBoatPopulationScoring(aiPlayer),
		MinimumTwoScouts(aiPlayer),
		AIProductionScoring_AlliedCombatFitnessVsStrongestEnemy(aiPlayer, 0.3, 0.8, 2, true)
	}

	if Util_IsPlayerRace(aiPlayer, "mongol") or AI_ArePlayersOnDifferentIslands() then
		result[#result +1 ] = AIProductionScoring_RemainingPersonnelPopCap(aiPlayer, 10)
	end

	return result
end

