function ScoringFunctions_WarShip(aiPlayer)
	local PersonalityScoreList = {
		AIProductionScoring_MinimumGameTime(aiPlayer, 15*60),
		AIProductionScoring_LuaScoringFunction(aiPlayer, PersonalityPick)
	}

	--Scoring for when the warship is a counter/personality pick
	local counterPickScoring = {
		AIProductionScoring_CounterScore(aiPlayer, 0.1),
		AIProductionScoring_MultiplyListScoringFunction(aiPlayer, PersonalityScoreList)
	}

		-- Scoring for need for warships to deal with defenses
	local regularSiegeDecisionBranch = {
		AIProductionScoring_PresenceOfEnemyTypes(aiPlayer, { ["stone_wall"] = 0.1, ["castle"] = 1.0, ["stone_wall_tower"] = 0.1, ["outpost"] = 0.1}, false)
	}

	local counterPickDecisionBranch =  AIProductionScoring_MaxScoringFunction(aiPlayer, counterPickScoring)
	local regularSiegeDecisionBranch = AIProductionScoring_MultiplyListScoringFunction(aiPlayer,regularSiegeDecisionBranch)

	-- We consider both possibilities and choose the max score
	local branchingDecisions = AIProductionScoring_MaxScoringFunction(aiPlayer, {counterPickDecisionBranch, regularSiegeDecisionBranch})

	local strategicTunings = { ["combat_naval"] = 1.0 }
	local result = {
		AIProductionScoring_StrategicIntention(aiPlayer, strategicTunings),
		AIProductionScoring_ShouldConsiderNaval(aiPlayer),
		AIProductionScoring_MultipleProduced(aiPlayer, 0.1),
		AIProductionScoring_TimeToAcquire(aiPlayer, 600.0, true, false, true),
		AIProductionScoring_MaxPopCapPercentage(aiPlayer, 0.15, true),
		branchingDecisions
	}
	return result
end

